{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "header_stack",
        "description_text",
        "table_sales",
        "insights_heading",
        "insight_home_goods",
        "insight_books"
      ]
    },
    "header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "icon_graph",
        "title_overview"
      ]
    },
    "icon_graph": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000276_01_1_graph-up.svg"
      },
      "children": []
    },
    "title_overview": {
      "type": "Text",
      "props": {
        "text": "Product Sales Overview",
        "variant": "h2"
      },
      "children": []
    },
    "description_text": {
      "type": "Text",
      "props": {
        "text": "This overview presents the sales performance across different product categories, highlighting key areas of strength."
      },
      "children": []
    },
    "table_sales": {
      "type": "Table",
      "props": {
        "title": "Product Category Sales Performance",
        "columns": [
          { "key": "Category", "label": "Category" },
          { "key": "Sales", "label": "Sales ($)" }
        ],
        "rows": [
          { "Category": "Electronics", "Sales": 12000 },
          { "Category": "Apparel", "Sales": 8500 },
          { "Category": "Home Goods", "Sales": 15000 },
          { "Category": "Books", "Sales": 4000 }
        ],
        "domain": "comparison",
        "preferredPresentation": "table",
        "numericColumns": ["Sales"],
        "primaryColumn": "Category"
      },
      "children": []
    },
    "insights_heading": {
      "type": "Text",
      "props": {
        "text": "Key Sales Insights",
        "variant": "h3"
      },
      "children": []
    },
    "insight_home_goods": {
      "type": "Text",
      "props": {
        "text": "Home Goods is the highest-selling category, generating $15,000 in sales."
      },
      "children": []
    },
    "insight_books": {
      "type": "Text",
      "props": {
        "text": "Books represent the lowest-selling category with $4,000 in sales."
      },
      "children": []
    }
  }
}
